import React, { useState } from 'react';
import { Card, CardContent, Typography, Box, Button, Chip, List, ListItem, ListItemText } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';

function RagAnalysisPage({ ragAnalysis, onBack }) {
  const [serverRecs, setServerRecs] = useState(null);
  const [generating, setGenerating] = useState(false);
  const [llmNotice, setLlmNotice] = useState(null);
  if (!ragAnalysis) {
    return (
      <Box sx={{ p: 4 }}>
        <Typography variant="h5">No RAG analysis data available.</Typography>
        <Button variant="contained" color="primary" onClick={onBack} sx={{ mt: 2 }}>
          <ArrowBackIcon sx={{ mr: 1 }} /> Back
        </Button>
      </Box>
    );
  }

  const { retrieved_docs } = ragAnalysis;
  const API_BASE = 'http://localhost:8000';

  const applyFrameFix = async (doc, action) => {
    try {
      const vid = ragAnalysis.video_id || null;
      const payload = {
        type: 'frame_fix',
        frame: doc.frame,
        timestamp: doc.timestamp,
        action: action,
        note: `Applied fix '${action}' to frame ${doc.frame}`,
        // If frontend knows a local source path, include it to allow ffmpeg processing server-side
        source_path: ragAnalysis.source_path || ragAnalysis.video_path || null
      };
      if (!vid) {
        console.warn('No video id available for apply');
      }
      const resp = await fetch(`${API_BASE}/api/videos/${vid}/apply`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      if (!resp.ok) {
        const txt = await resp.text().catch(() => '');
        throw new Error('Apply request failed: ' + txt);
      }
      const data = await resp.json();
      // If queued, poll the applied status endpoint until result_path available or timeout
      if (data && (data.status === 'queued' || data.status === 'ok') && data.applied_id) {
        const appliedId = data.applied_id;
        // Inform user that processing is queued
        // eslint-disable-next-line no-alert
        alert(`Apply job queued (id=${appliedId}). Waiting for server to finish processing...`);
        const maxTries = 30; // ~45s
        let tries = 0;
        while (tries < maxTries) {
          // wait
          // eslint-disable-next-line no-await-in-loop
          await new Promise(r => setTimeout(r, 1500));
          // eslint-disable-next-line no-await-in-loop
          const st = await fetch(`${API_BASE}/api/videos/${vid}/applied/${appliedId}`);
          if (st.ok) {
            // eslint-disable-next-line no-await-in-loop
            const sdat = await st.json();
            if (sdat && sdat.status === 'ok' && sdat.applied) {
              const rec = sdat.applied;
              if (rec.result_path) {
                window.open(rec.result_path, '_blank');
                return;
              }
              if (rec.status === 'error') {
                // eslint-disable-next-line no-alert
                alert('Processing failed: ' + (rec.error_message || JSON.stringify(rec)));
                return;
              }
            }
          }
          tries++;
        }
        // timed out
        // eslint-disable-next-line no-alert
        alert('Processing timed out. You can check the Applied Actions endpoint later.');
      } else if (data && data.result_path) {
        window.open(data.result_path, '_blank');
      } else {
        // eslint-disable-next-line no-alert
        alert('Apply response: ' + JSON.stringify(data));
      }
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('Apply failed', err);
      // eslint-disable-next-line no-alert
      alert('Apply failed: ' + (err.message || err));
    }
  };

  // Helper: get icon and color for frame type
  const getFrameIcon = (category) => {
    if (!category) return null;
    const cat = String(category).replace('_', ' ').toLowerCase();
    if ([
      'safe content',
      'educational content',
      'entertainment content',
      'news content',
      'tutorials & how-to',
      'community & family-friendly',
      'artistic & creative expression',
      'positive social impact'
    ].includes(cat)) {
      return <span style={{ color: '#43a047', fontWeight: 'bold', fontSize: 22 }}>✔️</span>;
    }
    return <span style={{ color: '#e53935', fontWeight: 'bold', fontSize: 22 }}>⚠️</span>;
  };

  // Define positive categories
  const positiveCategories = [
    'safe content',
    'educational content',
    'entertainment content',
    'news content',
    'tutorials & how-to',
    'community & family-friendly',
    'artistic & creative expression',
    'positive social impact'
  ];

  // Derive policy summaries if backend provides them, otherwise build from retrieved_docs
  const policySummaries = ragAnalysis.policy_summaries || ragAnalysis.policySummaries || (retrieved_docs && Array.isArray(retrieved_docs) ? (() => {
    const map = {};
    retrieved_docs.forEach(doc => {
      const cat = String(doc.category || '').toLowerCase();
      if (!cat) return;
      // Skip positive categories
      if (positiveCategories.includes(cat)) return;
      if (!map[cat]) {
        map[cat] = {
          category: doc.category || cat,
          description: (doc.policy && doc.policy.description) || doc.personalized_reason || doc.reasoning || doc.explanation || '',
          action_required: doc.action_required || (doc.policy && doc.policy.action_required) || ''
        };
      }
    });
    return Object.values(map);
  })() : []);

  // Group violations by type for summary, but skip positive categories
  const violationTypes = {};
  if (retrieved_docs && retrieved_docs.length > 0) {
    retrieved_docs.forEach(doc => {
      const cat = String(doc.category || '').toLowerCase();
      if (positiveCategories.includes(cat)) return; // skip positive
      if (!violationTypes[cat]) violationTypes[cat] = { count: 0, frames: [], actions: new Set(), reasons: new Set() };
      violationTypes[cat].count++;
      violationTypes[cat].frames.push(doc);
      if (doc.action_required) violationTypes[cat].actions.add(doc.action_required);
      if (doc.policy && doc.policy.description) violationTypes[cat].reasons.add(doc.policy.description);
      if (doc.reasoning) violationTypes[cat].reasons.add(doc.reasoning);
    });
  }
  const totalFrames = retrieved_docs ? retrieved_docs.length : 0;
  // Count safe frames and violation frames by their actual detected categories
  let safeFrames = 0;
  let violationFrames = 0;
  if (retrieved_docs && retrieved_docs.length > 0) {
    retrieved_docs.forEach(doc => {
      const cat = String(doc.category || '').toLowerCase();
      if (cat === 'safe content' || positiveCategories.includes(cat)) {
        safeFrames++;
      } else {
        violationFrames++;
      }
    });
  }
  const complianceRate = (ragAnalysis.compliance_rate || ragAnalysis.complianceRate || 0) * 100;

  // Derive pacing score if backend provides it (assume 1.0 == ideal).
  // Accepts possible field names: pacing_rate, pacingRate, pacingScore
  const pacingScore = ragAnalysis.pacing_rate || ragAnalysis.pacingRate || ragAnalysis.pacingScore || null;
  // Compute whether pacing is notably different from ideal (tunable threshold)
  const pacingDeviation = (typeof pacingScore === 'number') ? Math.abs(pacingScore - 1) : null;
  const pacingWarning = pacingDeviation !== null && pacingDeviation > 0.15; // warn if >15% deviation

  // Build grouped summary lines and collect all unique explanations for compliant videos
  let guidelineSummary = '';
  let guidelineReasons = [];
  let allExplanations = [];

  // Collect reasons and explanations from frames and RAG data (same as before)
  if (retrieved_docs && retrieved_docs.length > 0) {
    // If there are zero violation frames, give a short positive reason; otherwise gather violation reasons
    if (violationFrames === 0) {
      guidelineReasons = ['No violations detected. Content is safe and suitable for YouTube.'];
      const explanationsSet = new Set();
      retrieved_docs.forEach(doc => {
        if (doc.policy && doc.policy.description) explanationsSet.add(doc.policy.description);
        if (doc.reasoning) explanationsSet.add(doc.reasoning);
      });
      allExplanations = Array.from(explanationsSet);
    } else {
      if (ragAnalysis && ragAnalysis.rag_explanations && Array.isArray(ragAnalysis.rag_explanations)) {
        ragAnalysis.rag_explanations.forEach((exp) => {
          if (exp.policy) {
            let examples = '';
            if (Array.isArray(exp.policy.examples) && exp.policy.examples.length > 0) {
              examples = '\nExamples:';
              exp.policy.examples.forEach((ex, i) => {
                examples += `\n  ${i+1}. ${ex}`;
              });
            }
            let actionRequired = exp.policy.action_required ? `\nAction Required: ${exp.policy.action_required}` : '';
            let line = `${exp.category}:\n${exp.policy.description || ''}${examples}${actionRequired}`;
            guidelineReasons.push(line);
          }
        });
      } else {
        Object.entries(violationTypes).forEach(([cat, info]) => {
          const doc = info.frames[0] || {};
          let details = '';
          if (doc.policy && doc.policy.description) details += doc.policy.description + ' ';
          if (doc.personalized_reason) details += doc.personalized_reason + ' ';
          guidelineReasons.push(
            `${cat.replace('_', ' ')}: Detected in ${info.count} frame${info.count > 1 ? 's' : ''}. ${details.trim()}`
          );
        });
        if (safeFrames > 0) {
          const safeDoc = retrieved_docs.find(doc => {
            const cat = String(doc.category || '').toLowerCase();
            return cat === 'safe content' || positiveCategories.includes(cat);
          }) || {};
          let details = '';
          if (safeDoc.policy && safeDoc.policy.description) details += safeDoc.policy.description + ' ';
          guidelineReasons.push(
            `Safe: Detected in ${safeFrames} frame${safeFrames > 1 ? 's' : ''}. ${details.trim()}`
          );
        }
      }
      if (guidelineReasons.length === 0) {
        guidelineReasons = ['Violations detected, but no detailed policy explanation available.'];
      }
    }
  }

  // Determine top-level guideline summary based on complianceRate (consistent with header)
  if (complianceRate >= 90) {
    guidelineSummary = 'This video follows YouTube guidelines.';
  } else if (complianceRate >= 70) {
    guidelineSummary = 'This video follows YouTube guidelines, but with warnings.';
  } else if (complianceRate >= 50) {
    guidelineSummary = 'This video barely follows YouTube guidelines.';
  } else {
    guidelineSummary = 'This video does NOT follow YouTube guidelines.';
  }

  // Compute compliance rate and round for display
  const compliancePct = Math.round(complianceRate);

  // Banner logic (now driven by complianceRate to keep header and summary consistent)
  let bannerElement = null;
  if (complianceRate < 50) {
    // Major violations — red
    bannerElement = (
      <Card sx={{ mb: 3, backgroundColor: '#ffebee', border: '2px solid #f44336', color: '#b71c1c', borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
            ⛔ This video does NOT follow YouTube guidelines
          </Typography>
          {policySummaries && policySummaries.length > 0 ? (
            policySummaries.map((p, i) => (
              <Box key={i} sx={{ mb: 1 }}>
                <Typography variant="body2" sx={{ fontWeight: 'bold' }}>{(p.category || '').replace(/_/g, ' ')}:</Typography>
                <Typography variant="body2">{p.description}</Typography>
                {p.action_required && <Typography variant="body2" sx={{ fontStyle: 'italic' }}>Action Required: {p.action_required}</Typography>}
              </Box>
            ))
          ) : (
            guidelineReasons.map((r, i) => (
              <Typography key={i} variant="body2" sx={{ mb: 0.5 }}>{r}</Typography>
            ))
          )}
        </CardContent>
      </Card>
    );
  } else if (complianceRate >= 50 && complianceRate < 70) {
    // Barely passing — orange
    bannerElement = (
      <Card sx={{ mb: 3, backgroundColor: '#fff3e0', border: '2px solid #fb8c00', color: '#7a4300', borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
            ⚠️ This video passes YouTube guidelines but only barely
          </Typography>
          <Typography variant="body2" sx={{ mb: 1 }}>
            The video's compliance rate is {complianceRate}%, which is close to the minimum acceptable threshold. While no major violations were flagged, minor or borderline issues were detected. Review the analysis below and consider clarifying content or making small edits to improve safety and accessibility.
          </Typography>
          <Typography variant="body2">Recommended: review flagged frames, add clarifying context, or reduce dense/ambiguous content.</Typography>
        </CardContent>
      </Card>
    );
  } else if (complianceRate >= 70 && complianceRate < 90) {
    // Passes but with warnings — amber
    bannerElement = (
      <Card sx={{ mb: 3, backgroundColor: '#fffde7', border: '2px solid #ffb300', color: '#92400e', borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
            ⚠️ This video follows YouTube guidelines, but with warnings
          </Typography>
          <Typography variant="body2">Some content may require review or caution. See details below.</Typography>
        </CardContent>
      </Card>
    );
  } else if (complianceRate >= 90 && pacingWarning) {
    // Passes guidelines but pacing is off — show orange warning with explanation
    const paceText = pacingScore > 1 ? 'faster than typical' : 'slower than typical';
    bannerElement = (
      <Card sx={{ mb: 3, backgroundColor: '#fff8e1', border: '2px solid #ff9800', color: '#7a4300', borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
            ⚠️ This video passes guidelines but with pacing warnings
          </Typography>
          <Typography variant="body2" sx={{ mb: 1 }}>
            The video's pacing appears {paceText} (pacing score: {typeof pacingScore === 'number' ? pacingScore.toFixed(2) : 'N/A'}).
            Rapid or unusually slow pacing can reduce clarity, affect accessibility, or cause misunderstandings.
          </Typography>
          <Typography variant="body2">Recommended: review sections with dense speech or add brief pauses / visual cues to improve comprehension.</Typography>
        </CardContent>
      </Card>
    );
  } else {
    // Fully compliant (default)
    bannerElement = (
      <Card sx={{ mb: 3, backgroundColor: '#e8f5e9', border: '2px solid #2e7d32', color: '#1b5e20', borderRadius: 2 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
            ✅ This video follows YouTube guidelines
          </Typography>
          <Typography variant="body2">No violations detected. Content is safe and suitable for YouTube.</Typography>
        </CardContent>
      </Card>
    );
  }

  // Determine summary card colors from compliance rate bands (keeps header and summary visuals consistent)
  let summaryBg = '#e8f5e9';
  let summaryBorder = undefined;
  let summaryTextColor = '#43a047';
  if (compliancePct < 50) {
    summaryBg = '#ffebee';
    summaryBorder = '2px solid #e53935';
    summaryTextColor = '#e53935';
  } else if (compliancePct >= 50 && compliancePct < 70) {
    summaryBg = '#fff3e0';
    summaryBorder = '2px solid #fb8c00';
    summaryTextColor = '#7a4300';
  } else if (compliancePct >= 70 && compliancePct < 90) {
    summaryBg = '#fffde7';
    summaryBorder = '2px solid #ffb300';
    summaryTextColor = '#92400e';
  }

  const complianceChipColor = compliancePct >= 90 ? 'success' : compliancePct < 50 ? 'error' : 'default';

  return (
    <Box sx={{ p: 5, background: 'linear-gradient(120deg, #e3f2fd 60%, #fffde7 100%)', minHeight: '100vh' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
        <Button variant="outlined" color="secondary" sx={{ mr: 2, fontWeight: 'bold', borderRadius: 3 }} onClick={onBack}>
          ← Back
        </Button>
        <Typography variant="h4" color="primary" sx={{ fontWeight: 'bold' }}>
          RAG Policy Violation Explanations
        </Typography>
      </Box>
      {/* YouTube-style guideline summary */}
      <Card sx={{ maxWidth: 900, mb: 3, boxShadow: 3, borderRadius: 3, p: 2, background: summaryBg, border: summaryBorder }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 'bold', color: summaryTextColor, mb: 1 }}>
            {guidelineSummary}
          </Typography>
          {guidelineReasons.map((reason, idx) => (
            <Typography key={idx} variant="body2" sx={{ mb: 0.5, color: summaryTextColor, fontWeight: 'bold' }}>{reason}</Typography>
          ))}
          {/* Prominent explanation section for compliant videos */}
          {violationFrames === 0 && allExplanations.length > 0 && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 'bold', color: '#1976d2', mb: 1 }}>
                Content Explanations:
              </Typography>
              {allExplanations.map((exp, idx) => (
                <Typography key={idx} variant="body2" sx={{ mb: 0.5, color: '#1976d2' }}>{exp}</Typography>
              ))}
            </Box>
          )}
          <Box sx={{ display: 'flex', gap: 2, mt: 2 }}>
            <Chip label={`Compliance Rate: ${compliancePct}%`} color={complianceChipColor} sx={{ fontWeight: 'bold' }} />
            <Chip label={`Safe Frames: ${safeFrames}`} color="success" sx={{ fontWeight: 'bold' }} />
            <Chip label={`Violations: ${violationFrames}`} color="error" sx={{ fontWeight: 'bold' }} />
            <Chip label={`Total Frames: ${totalFrames}`} color="primary" sx={{ fontWeight: 'bold' }} />
            <Box sx={{ display: 'flex', gap: 1, ml: 2 }}>
              <Button size="small" variant="contained" color="primary" onClick={async () => {
                if (generating) return;
                setGenerating(true);
                setLlmNotice(null);
                try {
                  const resp = await fetch(`${API_BASE}/api/videos/${ragAnalysis.video_id}/recommendations/generate`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(ragAnalysis) });
                  if (!resp.ok) throw new Error(await resp.text());
                  const data = await resp.json();
                  if (data && data.recommendations) setServerRecs(data.recommendations);
                } catch (e) {
                  // eslint-disable-next-line no-alert
                  alert('Failed to generate recommendations: ' + (e.message || e));
                }
                setGenerating(false);
              }}>{generating ? 'Generating...' : 'Generate Personalized Recommendations'}</Button>

              <Button size="small" variant="outlined" color="secondary" onClick={async () => {
                if (generating) return;
                setGenerating(true);
                setLlmNotice(null);
                try {
                  const resp = await fetch(`${API_BASE}/api/videos/${ragAnalysis.video_id}/recommendations/llm`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(ragAnalysis) });
                  if (!resp.ok) throw new Error(await resp.text());
                  const data = await resp.json();
                  if (data) {
                    // If LLM unavailable, backend returns status 'llm_unavailable' with setup_url and fallback recs
                    if (data.status === 'llm_unavailable') {
                      setServerRecs(data.recommendations || []);
                      setLlmNotice({ message: data.message || 'Local LLM unavailable', setup_url: data.setup_url || '/local-llm-setup', error: data.error || null });
                    } else if (data.recommendations) {
                      setServerRecs(data.recommendations);
                    }
                  }
                } catch (e) {
                  // eslint-disable-next-line no-alert
                  alert('LLM request failed: ' + (e.message || e));
                }
                setGenerating(false);
              }}>Generate via Local LLM</Button>
            </Box>
          </Box>
        </CardContent>
      </Card>
      {/* LLM availability notice (shown when backend indicates LLM unreachable) */}
      {llmNotice && (
        <Card sx={{ maxWidth: 900, mb: 3, boxShadow: 1, borderRadius: 2, p: 2, backgroundColor: '#fff8e1' }}>
          <CardContent>
            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>Local LLM unavailable</Typography>
            <Typography variant="body2" sx={{ mb: 1 }}>{llmNotice.message}</Typography>
            {llmNotice.error && <Typography variant="caption" sx={{ display: 'block', color: 'error.main' }}>Error: {llmNotice.error}</Typography>}
            <Box sx={{ mt: 1 }}>
              <Button size="small" variant="outlined" color="primary" onClick={() => window.open(`${API_BASE}${llmNotice.setup_url}`, '_blank')}>Open local LLM setup</Button>
            </Box>
          </CardContent>
        </Card>
      )}
      {/* Server-generated recommendations display */}
      {serverRecs && (
        <Card sx={{ maxWidth: 900, mb: 3, boxShadow: 3, borderRadius: 3, p: 2 }}>
          <CardContent>
            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>Personalized Fixes & Recommendations</Typography>
            <List>
              {serverRecs.map((r, i) => (
                <ListItem key={i} alignItems="flex-start">
                  <ListItemText primary={<strong>{(r.category || '').toUpperCase()}</strong>} secondary={
                    <>
                      <Typography component="span" variant="body2" color="text.primary">{r.description}</Typography>
                      {r.examples && r.examples.length > 0 && (
                        <Typography variant="caption" display="block">Examples: {r.examples.join(', ')}</Typography>
                      )}
                      <Typography variant="body2" sx={{ mt: 1 }}><strong>Suggested:</strong> {r.suggested_action}</Typography>
                      {r.quick_wins && r.quick_wins.length > 0 && (
                        <Box sx={{ mt: 1 }}>
                          <Typography variant="subtitle2">Quick wins:</Typography>
                          {r.quick_wins.map((q, qi) => <Typography key={qi} variant="body2">• {q}</Typography>)}
                        </Box>
                      )}
                    </>
                  } />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      )}
      {bannerElement}
      {/* Frame-by-frame cards */}
      <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(420px, 1fr))', gap: 3 }}>
        {retrieved_docs && retrieved_docs.length > 0 ? (
          <>
            {retrieved_docs.map((doc, idx) => {
              const cat = String(doc.category || '').toLowerCase();
              const isPositive = positiveCategories.includes(cat);
              // Build a summary of what the frame contains
              let frameSummary = [];
              if (doc.blip) frameSummary.push(`BLIP: ${doc.blip}`);
              if (doc.ocr) frameSummary.push(`OCR: ${doc.ocr}`);
              if (doc.transcript) frameSummary.push(`Transcript: ${doc.transcript}`);
              if (doc.keywords && doc.keywords.length > 0) frameSummary.push(`Keywords: ${doc.keywords.join(', ')}`);
              if (doc.policy && doc.policy.description) frameSummary.push(`Policy: ${doc.policy.description}`);
              if (doc.reasoning) frameSummary.push(`Explication: ${doc.reasoning}`);
              if (doc.rag) frameSummary.push(`RAG Explanation: ${typeof doc.rag === 'string' ? doc.rag : JSON.stringify(doc.rag)}`);
              if (doc.personalized_reason) frameSummary.push(`Personalized Reason: ${doc.personalized_reason}`);
              if (doc.explanation) frameSummary.push(`Explanation: ${doc.explanation}`);
              if (doc.examples && doc.examples.length > 0) frameSummary.push(`Examples: ${doc.examples.join(', ')}`);
              if (doc.action_required) frameSummary.push(`Action Required: ${doc.action_required}`);
              if (doc.severity_indicators && doc.severity_indicators.length > 0) frameSummary.push(`Severity Indicators: ${doc.severity_indicators.join(', ')}`);
              if (doc.context_factors && doc.context_factors.length > 0) frameSummary.push(`Context Factors: ${doc.context_factors.join(', ')}`);

              return (
                <Card key={idx} sx={{ background: isPositive ? '#f9fbe7' : '#ffebee', borderRadius: 3, boxShadow: 2 }}>
                  <CardContent>
                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                      {getFrameIcon(doc.category)}
                      <Typography variant="subtitle1" sx={{ fontWeight: 'bold', ml: 1, color: isPositive ? '#fff' : 'error.main', background: isPositive ? '#1976d2' : undefined, px: 1, borderRadius: 1 }}>
                        {doc.title || doc.category || 'Frame'}
                      </Typography>
                    </Box>
                    {doc.frame !== undefined && (
                      <Typography variant="body2" sx={{ mb: 0.5 }}>
                        <b>Frame #:</b> {doc.frame}
                      </Typography>
                    )}
                    {doc.timestamp !== undefined && (
                      <Typography variant="body2" sx={{ mb: 0.5 }}>
                        <b>Timestamp:</b> {doc.timestamp}s
                      </Typography>
                    )}
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 1 }}>
                      {doc.category && (
                        <Chip label={`Category: ${doc.category}`} color={isPositive ? 'success' : 'primary'} sx={{ fontWeight: 'bold', background: isPositive ? '#388e3c' : undefined, color: isPositive ? '#fff' : undefined }} />
                      )}
                      {doc.confidence !== undefined && (
                        <Chip label={`Confidence: ${doc.confidence}`} color="success" />
                      )}
                    </Box>
                    {/* Frame summary section */}
                    {frameSummary.length > 0 && (
                      <Box sx={{ mt: 1, mb: 1, background: '#e3f2fd', borderRadius: 2, p: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 'bold', color: '#1976d2', mb: 0.5 }}>Frame Details:</Typography>
                        {frameSummary.map((line, i) => (
                          <Typography key={i} variant="body2" sx={{ color: '#1976d2', mb: 0.5 }}>{line}</Typography>
                        ))}
                        <Box sx={{ mt: 1, display: 'flex', gap: 1 }}>
                          {!isPositive && (
                            <Button size="small" variant="contained" color="warning" onClick={() => applyFrameFix(doc, 'blur')}>Apply Blur</Button>
                          )}
                          <Button size="small" variant="outlined" color="primary" onClick={() => applyFrameFix(doc, 'annotate')}>Annotate</Button>
                        </Box>
                      </Box>
                    )}
                  </CardContent>
                </Card>
              );
            })}
          </>
        ) : (
          <Typography>No RAG explanations found.</Typography>
        )}
      </Box>
    </Box>
  );
}

export default RagAnalysisPage;
